import itertools, json
jobs='ABCDE'
slot=dict(zip(jobs,[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]))
trans=dict(zip(jobs,[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]))
def nominal(p):
 return sum(slot[j][i] for i,j in enumerate(p))+sum(trans[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def legal(p,s):
 if p.index('A')>p.index('D'): return False
 return {'rain':p[1]!='E' and p[4]!='D','road':p[4]!='B' and p[0]!='D','lift':p[3]!='D' and p[0]!='C'}[s]
def penalty(p,s):
 j,t,k={'rain':('A',2,6),'road':('C',3,8),'lift':('E',1,5)}[s]
 return k*max(0,p.index(j)+1-t)
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'): continue
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p);q[i],q[j]=q[j],q[i]
  neighbors.append((tuple(q),4))
 best={}
 for s in ['rain','road','lift']:
  choices=[(nominal(q)+penalty(q,s)+fee,''.join(q)) for q,fee in neighbors if legal(q,s)]
  if not choices: break
  best[s]=min(choices)
 if len(best)==3:
  results.append((nominal(p)+max(v[0] for v in best.values()),''.join(p),best))
results.sort()
score,p,best=results[0]
answer={'roster':p,'score':score,'repairs':{s:v[1] for s,v in best.items()},'repair_costs':{s:v[0] for s,v in best.items()},'feasible_count':len(results),'next_score':min(v[0] for v in results if v[0]>score)}
print(json.dumps(answer))
print('published nominal',nominal(p),'optima',sum(r[0]==score for r in results))
for s,(cost,q) in best.items():
 print(s,q,'slot',sum(slot[j][i] for i,j in enumerate(q)),'transfer',sum(trans[a][jobs.index(b)] for a,b in zip(q,q[1:])),'penalty',penalty(q,s),'fee',4*(q!=p))
# Independent enumeration of final permutations using Hamming distance 0 or 2.
allp=[''.join(q) for q in itertools.permutations(jobs) if q.index('A')<q.index('D')]
check=[]
for pub in allp:
 vals=[]
 for s in ['rain','road','lift']:
  cs=[]
  for final in allp:
   distance=sum(a!=b for a,b in zip(pub,final))
   if distance not in (0,2) or not legal(final,s): continue
   cs.append(nominal(final)+penalty(final,s)+(4 if distance else 0))
  if not cs: break
  vals.append(min(cs))
 if len(vals)==3: check.append(nominal(pub)+max(vals))
assert len(check)==answer['feasible_count']
assert min(check)==score
assert min(x for x in check if x>score)==answer['next_score']
assert all(nominal(q)+penalty(q,s)+4*(q!=p)==best[s][0] for s,q in answer['repairs'].items())
print('Independent final-permutation cross-check passed')

