import itertools,json
jobs='ABCDE'; pub='ACEBD'
slots=[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]
trans=[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]
def distance(q):
 perm=[pub.index(j) for j in q]; seen=set(); cycles=0
 for i in range(5):
  if i not in seen:
   cycles+=1
   while i not in seen:
    seen.add(i);i=perm[i]
 return 5-cycles
def cost(q,d):
 return sum(slots[jobs.index(j)][i] for i,j in enumerate(q))+sum(trans[jobs.index(a)][jobs.index(b)] for a,b in zip(q,q[1:]))+6*max(0,q.index('A')+1-2)+4*d+5*(d==2)
groups={d:[] for d in range(3)}
for tup in itertools.permutations(jobs):
 q=''.join(tup);d=distance(q)
 if d>2 or q.index('A')>q.index('D') or q[1]=='E' or q[4]=='D' or q[2]=='E':continue
 groups[d].append((cost(q,d),q))
best=min(x for g in groups.values() for x in g)
answer={'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(v)[0] if v else None for d,v in groups.items()},'feasible_by_swaps':{str(d):len(v) for d,v in groups.items()}}
# Independently verify minimum exchange distances by breadth-first search.
levels={pub:0};front=[pub]
for d in [1,2]:
 nxt=[]
 for p in front:
  for i,j in itertools.combinations(range(5),2):
   q=list(p);q[i],q[j]=q[j],q[i];q=''.join(q)
   if q not in levels:levels[q]=d;nxt.append(q)
 front=nxt
assert all(distance(q)==d for q,d in levels.items())
for d,entries in groups.items():
 assert all(levels[q]==d for c,q in entries)
print(json.dumps(answer))
print('Verified BFS distances; best entries:',{d:sorted(v)[:3] for d,v in groups.items()})

